import {GUIDE_STEPS,SOURCE_LABELS,guidedSnapshot} from './guided-model.js';
import {createMatchPitch} from './match-pitch.js';
import {matchSession} from './match-session.js';
import {SCENARIOS} from './engine.js';
import {PRESENTER_PROFILES} from './presenter-profiles.js';
import {ROLE_LABELS} from './editorial-roles.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const button=(text,action,cls='outline-button')=>{const b=el('button',cls,text);b.type='button';b.onclick=action;return b;};
const save=(filename,data)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const watch=document.getElementById('watch');let active=false,step=0,options={time:16,corrected:false,language:'en',mode:'analyst'},pack=null,playing=false,touring=false,lastFrame=0,tourStart=0;
const launcher=el('section','guided-launch'),intro=el('div');intro.append(el('span','eyebrow','START HERE / THE BTR EXPERIENCE'),el('strong','','One play. Every perspective. A story you can question.'),el('p','','Follow the football, meet the crew, and see the explanation change when the evidence changes.'));
const open=button('Explore the guided match →',()=>enter(), 'red-button'),filmButton=button('Watch the 60-second film',()=>leave('pitchside'));launcher.append(intro,open,filmButton);watch.prepend(launcher);
const tour=el('section','guided-tour');tour.id='guided-match';tour.hidden=true;tour.setAttribute('aria-label','Guided match demonstration');launcher.after(tour);
const top=el('div','guided-top'),badge=el('b','','INTERACTIVE DEMO · NO AI REQUESTS'),source=el('span','','SYNTHETIC MATCH · THE UNSEEN RUN'),auto=button('Play the 105-second tour',()=>{if(touring){stopTour();return;}options={...options,time:0,corrected:false};step=0;touring=true;playing=true;tourStart=performance.now();lastFrame=0;render();}),exit=button('Explore the app ↗',()=>leave('match'));top.append(badge,source,auto,exit);tour.append(top);
const topFilm=button('Watch the film',()=>leave('pitchside'));top.insertBefore(topFilm,exit);
const steps=el('nav','guided-steps');steps.setAttribute('aria-label','Guided match stages');for(const [index,s]of GUIDE_STEPS.entries())steps.append(button(`${index+1} · ${s.label}`,()=>{stopTour();setStep(index);},''));tour.append(steps);
const grid=el('div','guided-grid'),screen=el('section','guided-screen'),score=el('div','guided-score');score.append(el('b','','HARBOR'),el('strong','','0 : 0'),el('b','','NORTHBRIDGE'));const clock=el('span','','67:16 · R1');score.append(clock);screen.append(score);
const pitchNode=el('div','guided-pitch');screen.append(pitchNode);const pitch=createMatchPitch(pitchNode,()=>{});
const caption=el('div','guided-caption'),captionMeta=el('small','','ON SCREEN · SYNTHETIC EVIDENCE'),captionTitle=el('h3'),captionCopy=el('p');caption.append(captionMeta,captionTitle,captionCopy);screen.append(caption);
const controls=el('div','guided-controls'),play=button('▶ Replay the play',()=>{stopTour();playing=!playing;if(playing&&options.time>=16)options.time=0;lastFrame=0;render();}),scrub=el('input');scrub.type='range';scrub.min='0';scrub.max='16';scrub.step='.1';scrub.value='16';scrub.setAttribute('aria-label','Guided match time');scrub.oninput=()=>{stopTour();playing=false;options.time=Number(scrub.value);render();};controls.append(play,scrub);screen.append(controls);grid.append(screen);
const copy=el('article','guided-copy'),kicker=el('span','eyebrow'),heading=el('h2'),description=el('p'),content=el('div','guided-content');heading.tabIndex=-1;copy.append(kicker,heading,description,content);grid.append(copy);tour.append(grid);
const nextRow=el('div','guided-next'),stateLabel=el('span','guided-note'),back=button('← Back',()=>{stopTour();setStep(step-1);}),next=button('Next →',()=>{stopTour();if(step===4)leave('match');else setStep(step+1);},'red-button');nextRow.append(back,stateLabel,next);copy.append(nextRow);
const provenance=el('p','guided-source');tour.append(provenance);
const downloadRow=el('div','guided-downloads');downloadRow.append(button('Download story + evidence ↓',()=>save('btr-guided-story.json',guidedSnapshot(options,pack).export)),button('Compare agent results ↗',()=>{leave('match');document.getElementById('inside-nav').click();document.getElementById('judge-evidence').scrollIntoView({block:'start',behavior:'smooth'});}));tour.append(downloadRow);
const map=el('details','source-map');map.append(el('summary','','What am I watching? Three clearly identified sources'));for(const entry of Object.values(SOURCE_LABELS)){const row=el('article');row.append(el('strong','',entry.title),el('p','',entry.scope));map.append(row);}document.querySelector('.watch-source-bar').after(map);
const proof=el('section','judge-evidence');proof.id='judge-evidence';proof.setAttribute('aria-label','Measured agent evaluation');proof.append(el('h2','','The evidence behind the experience'),el('p','','The guided match always works with reviewed notes and calculated facts. Saved model contributions, when available, are labeled with their recording date. Live generation remains a separate action.'));
const evaluation=el('div');evaluation.append(el('p','','Evaluation results are loading. The downloadable verification summary remains available.'));proof.append(evaluation);
const links=el('p');for(const [href,label]of [['assets/btr-agent-evaluation.json','Agent comparison + raw contributions'],['assets/btr-verification-summary.json','Recovery verification'],['assets/btr-recording-guide.txt','105-second demonstration script']]){const a=el('a','',label);a.href=href;a.download='';links.append(a,document.createTextNode(' · '));}proof.append(links);document.querySelector('#inside .extension-heading').after(proof);
const walkthrough=el('a','proof-output','Watch the 105-second illustrated walkthrough ↗');walkthrough.href='assets/btr-guided-walkthrough.mp4';walkthrough.target='_blank';walkthrough.rel='noopener';proof.append(walkthrough,el('p','guided-note','The walkthrough renders the app’s synthetic coordinates, calculations and reviewed explanations. It contains no cinematic footage or audio. It is labeled as an illustration, not a browser recording or a fresh AI run.'));
const repository=el('a','proof-output','Inspect the public source on GitHub ↗');repository.href='https://github.com/sagitta414/before-the-roar';repository.target='_blank';repository.rel='noopener';proof.append(repository);
function stopTour(){touring=false;auto.textContent='Play the 105-second tour';}
function sync(){matchSession.set({...options,source:'match',scenario:'wide',focus:7,team:'harbor'},'guided');}
function enter(){document.getElementById('film').pause();active=true;document.body.classList.add('guided-active');tour.hidden=false;open.textContent='Restart guided match ↺';document.dispatchEvent(new CustomEvent('btr-guided-activity',{detail:true}));matchSession.set({scenario:'wide',source:'match'},'guided');options.time=16;step=0;options.corrected=false;render();}
function leave(source){stopTour();playing=false;active=false;tour.hidden=true;document.body.classList.remove('guided-active');open.textContent='Explore the guided match →';document.dispatchEvent(new CustomEvent('btr-guided-activity',{detail:false}));matchSession.set({source},'guided-exit');try{sessionStorage.setItem('btr-guided-dismissed','1');}catch{}}
function setStep(index){step=Math.max(0,Math.min(4,index));playing=false;options.time=16;render();heading.focus({preventScroll:true});}
function renderPitch(snapshot){pitch.update(SCENARIOS[0],snapshot.story.brief.state,7,options.corrected);clock.textContent=snapshot.story.clock+' · R'+snapshot.story.revision;scrub.value=String(options.time);captionTitle.textContent=snapshot.story.title;captionCopy.textContent=snapshot.story.body;captionMeta.textContent=`ON SCREEN · R${snapshot.story.revision} · ${options.language.toUpperCase()} · ${snapshot.story.words[options.mode]}`;play.textContent=playing?'❚❚ Pause':'▶ Replay the play';}
function render(){if(!active)return;sync();const snapshot=guidedSnapshot(options,pack);renderPitch(snapshot);const s=GUIDE_STEPS[step];kicker.textContent=`${String(step+1).padStart(2,'0')} / ${s.label.toUpperCase()}`;heading.textContent=s.title;description.textContent=s.copy;auto.textContent=touring?'Pause tour':'Play the 105-second tour';for(const [i,b]of [...steps.children].entries()){if(i===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');}back.disabled=step===0;next.textContent=step===4?'Continue exploring →':`Next: ${GUIDE_STEPS[step+1].label} →`;stateLabel.textContent=`${step+1} of 5 · ${snapshot.story.clock} · Source R${snapshot.story.revision}`;
 provenance.textContent=snapshot.saved?`Saved Azure run · ${new Date(snapshot.recordedAt).toLocaleDateString()} · Replayed instantly, with no new AI generation. Each contribution identifies its engine.`:'Reviewed demonstration · authored explanations and calculations run in your browser. No fresh AI generation or model requests. Live AI is available in Watch and the production desk.';
 content.replaceChildren();
 if(step===0){if(options.time<16)description.textContent='Follow the ball, winger and defender as the recorded play arrives. The caption uses only evidence through the current playhead.';const fact=el('div','guided-verdict');fact.append(el('strong','','WATCH THE WIDE CHANNEL'),el('span','',options.time<16?'Follow the space beside the winger. Wait for the reached tracking samples before drawing a conclusion about the defender’s movement.':'The winger moves toward the touchline as the defender shifts toward the same side. The timing suggests a tactical relationship; it does not establish why the defender moved.'));content.append(fact,el('p','guided-note','Replay the first sixteen seconds, or move straight to the crew. All positions and events are authored synthetic data.'));
 }else if(step===1){for(const p of snapshot.posts){const profile=PRESENTER_PROFILES.find(r=>r.id===p.role),row=el('article','guided-role'),img=el('img');img.src=`assets/${profile.image}-portrait.webp`;img.alt='';const text=el('div'),meta=el('div');meta.append(el('b','',profile.name+' / '+ROLE_LABELS[options.language][p.role]),el('small','',p.engine==='azure_openai'?'SAVED AI':p.engine==='calculated'?'CALCULATED':p.engine==='evidence_rules'?'SOURCE CHECK':'REVIEWED NOTE'));text.append(meta,el('p','',p.summary));const detail=el('details');detail.append(el('summary','','Evidence + limits'),el('code','',p.evidence_ids.join(' · ')));if(p.working)detail.append(el('code','',p.working));if(p.caution)detail.append(el('p','',p.caution));text.append(detail);row.append(img,text);content.append(row);}
 }else if(step===2){const metric=snapshot.story.analysis.calculations[0],card=el('div','guided-metric'),text=el('div');text.append(el('b','',metric.label),el('p','',metric.text));card.append(el('strong','',metric.value),text);content.append(card);const details=el('details');details.open=true;details.append(el('summary','','Recalculate from the recorded passes'),el('code','',metric.equation));for(const e of snapshot.story.analysis.passes)details.append(el('p','guided-note',`${e.id}: x ${e.start[0].toFixed(2)} → ${e.endPosition[0].toFixed(2)} m · completed`));content.append(details,el('p','guided-note','Football meaning: the passes advance the ball toward goal. This is one short sequence, not a team average or a measure of chance quality.'));
 }else if(step===3){const verdict=el('div','guided-verdict');verdict.dataset.corrected=String(options.corrected);verdict.append(el('strong','',options.corrected?'WITHDRAWN · R2':'QUALIFIED · R1'),el('span','',snapshot.story.review.reason));content.append(verdict,button(options.corrected?'Restore original record':'Apply corrected tracking',()=>{options.corrected=!options.corrected;render();},'red-button'),el('p','guided-note',`${snapshot.story.stats} The pass records do not change. The caption and defender position update together.`));
 }else{const preferences=el('div','guided-preferences');for(const [key,title,items]of [['mode','YOUR PERSPECTIVE',[['beginner','New to football'],['math','Show the math'],['analyst','Tactical view']]],['language','YOUR LANGUAGE',[['en','English'],['es','Español'],['pt','Português']]]]){const label=el('label','',title),select=el('select');select.setAttribute('aria-label','Guided '+title.toLowerCase());for(const [value,text]of items){const opt=el('option','',text);opt.value=value;select.append(opt);}select.value=options[key];select.onchange=()=>{stopTour();options[key]=select.value;render();};label.append(select);preferences.append(label);}content.append(preferences,el('p','guided-note','These captions are localized from the same evidence. Changing a language or perspective never changes the facts.'));const feedback=el('details');feedback.append(el('summary','','Help test the experience'));const question=el('p','','After this demonstration, can you explain why the claim changed?');feedback.append(question);for(const answer of ['Yes, clearly','Partly','Not yet'])feedback.append(button(answer,()=>{save('btr-viewer-feedback.json',{schema:'btr.viewer-feedback.v1',recorded_at:new Date().toISOString(),answer,source:'voluntary-local-download',task:'Explain the correction',...options});}));feedback.append(el('p','guided-note','Downloads your feedback locally. Nothing is sent or counted as a user study automatically.'));content.append(feedback);}
}
let lastPaint=0;function frame(now){if(active&&(playing||touring)){if(touring){const elapsed=(now-tourStart)/1000,index=elapsed>=72?4:elapsed>=52?3:elapsed>=36?2:elapsed>=18?1:0;if(index!==step){step=index;options.time=16;playing=false;render();}if(step===0){options.time=Math.min(16,elapsed);playing=elapsed<16;}if(step===3&&elapsed>=60&&!options.corrected){options.corrected=true;render();}if(step===4){const mode=elapsed>=91?'math':'beginner',language=elapsed>=83?'es':'en';if(options.mode!==mode||options.language!==language){options.mode=mode;options.language=language;render();}}if(elapsed>=105){stopTour();playing=false;render();}}else if(playing&&lastFrame){options.time=Math.min(16,options.time+(now-lastFrame)/1000);if(options.time>=16){playing=false;render();}}if(now-lastPaint>100){lastPaint=now;sync();renderPitch(guidedSnapshot(options,pack));}lastFrame=now;}else lastFrame=0;requestAnimationFrame(frame);}requestAnimationFrame(frame);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTour();playing=false;}});
document.addEventListener('btr-section',e=>{if(e.detail!=='watch'){stopTour();playing=false;active=false;tour.hidden=true;document.body.classList.remove('guided-active');open.textContent='Explore the guided match →';document.dispatchEvent(new CustomEvent('btr-guided-activity',{detail:false}));}});
document.addEventListener('btr-open-guided',()=>{document.getElementById('watch-nav').click();enter();});
fetch('assets/btr-agent-evaluation.json').then(r=>{if(!r.ok)throw Error('No measured evaluation yet');return r.json();}).then(data=>{pack=data;evaluation.replaceChildren();const table=el('table');const head=el('tr');for(const t of ['Measured check','Agent team','Single model'])head.append(el('th','',t));table.append(head);for(const [label,key]of [['Accepted editorial outputs','accepted'],['Guard-rejected outputs','rejected'],['Model requests','requests'],['Wall time (seconds)','seconds']]){const row=el('tr');row.append(el('th','',label));for(const arm of ['team','baseline'])row.append(el('td','',String(data.summary?.[arm]?.[key]??'Not measured')));table.append(row);}evaluation.append(el('p','',`${data.cases.length} fixed cases · ${data.model} · recorded ${new Date(data.recorded_at).toLocaleString()}`),table,el('p','',data.conclusion),el('p','guided-note','Engineering and editorial guard checks on a small fixed set. These checks do not establish semantic accuracy, superiority, or audience satisfaction. The baseline receives the same evidence and calculated facts.'));if(active)render();}).catch(()=>{evaluation.replaceChildren(el('p','','No completed live comparison is published yet. The evaluation harness and its fixed cases are available in the project source. No superiority claim is made.'));});
let dismissed=false;try{dismissed=sessionStorage.getItem('btr-guided-dismissed')==='1';}catch{}
if(new URLSearchParams(location.search).has('tour')||(!dismissed&&(!location.hash||location.hash==='#watch')))enter();
fetch('media-availability.json').then(r=>r.ok?r.json():null).then(media=>{if(media?.pitchside!==false)return;for(const b of [filmButton,topFilm]){b.disabled=true;b.textContent='Optional film not included';}document.querySelector('#watch-source option[value="pitchside"]').disabled=true;document.querySelector('.source-details a')?.setAttribute('hidden','');if(matchSession.get().source==='pitchside')matchSession.set({source:'match'});}).catch(()=>{});
